ALTER TYPE "QuestionType" ADD VALUE 'MULTIPLE_SELECT';
ALTER TYPE "QuestionType" ADD VALUE 'SHORT_ANSWER';
ALTER TYPE "QuestionType" ADD VALUE 'ESSAY';
CREATE TYPE "QuizStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "QuizAttemptStatus" AS ENUM ('IN_PROGRESS','SUBMITTED','UNDER_REVIEW','GRADED');
CREATE TYPE "QuestionDifficulty" AS ENUM ('EASY','MEDIUM','HARD');
ALTER TABLE "Quiz" ADD COLUMN "description" TEXT, ADD COLUMN "status" "QuizStatus" NOT NULL DEFAULT 'DRAFT', ADD COLUMN "availableFrom" TIMESTAMP(3), ADD COLUMN "availableUntil" TIMESTAMP(3), ADD COLUMN "maxAttempts" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "shuffleQuestions" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "shuffleOptions" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "showResults" BOOLEAN NOT NULL DEFAULT true, ADD COLUMN "highStakes" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "proctoringConfigJson" TEXT;
ALTER TABLE "Question" ALTER COLUMN "quizId" DROP NOT NULL, ALTER COLUMN "correctAnswer" DROP NOT NULL, ADD COLUMN "explanation" TEXT, ADD COLUMN "tags" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "difficulty" "QuestionDifficulty" NOT NULL DEFAULT 'MEDIUM', ADD COLUMN "isBankQuestion" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "order" INTEGER NOT NULL DEFAULT 1;
ALTER TABLE "QuizAttempt" ADD COLUMN "status" "QuizAttemptStatus" NOT NULL DEFAULT 'IN_PROGRESS', ADD COLUMN "attemptNumber" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "expiresAt" TIMESTAMP(3), ADD COLUMN "lastSavedAt" TIMESTAMP(3), ADD COLUMN "submittedAt" TIMESTAMP(3), ADD COLUMN "gradedAt" TIMESTAMP(3), ADD COLUMN "reviewedById" TEXT, ADD COLUMN "reviewNote" TEXT;
CREATE TABLE "QuizQuestion" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "quizId" TEXT NOT NULL, "questionId" TEXT NOT NULL, "order" INTEGER NOT NULL, "pointsOverride" DOUBLE PRECISION, CONSTRAINT "QuizQuestion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuizAnswer" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "attemptId" TEXT NOT NULL, "questionId" TEXT NOT NULL, "answerJson" TEXT NOT NULL, "score" DOUBLE PRECISION, "isCorrect" BOOLEAN, "feedback" TEXT, "manuallyGraded" BOOLEAN NOT NULL DEFAULT false, "savedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "gradedAt" TIMESTAMP(3), CONSTRAINT "QuizAnswer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuizAuditEvent" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "quizId" TEXT NOT NULL, "attemptId" TEXT, "userId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "metadataJson" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "QuizAuditEvent_pkey" PRIMARY KEY ("id"));
INSERT INTO "QuizQuestion" ("id","organizationId","quizId","questionId","order") SELECT gen_random_uuid()::text,"organizationId","quizId","id","order" FROM "Question" WHERE "quizId" IS NOT NULL;
CREATE UNIQUE INDEX "QuizAttempt_organizationId_quizId_studentId_attemptNumber_key" ON "QuizAttempt"("organizationId","quizId","studentId","attemptNumber");
CREATE UNIQUE INDEX "QuizQuestion_organizationId_quizId_questionId_key" ON "QuizQuestion"("organizationId","quizId","questionId"); CREATE UNIQUE INDEX "QuizQuestion_organizationId_quizId_order_key" ON "QuizQuestion"("organizationId","quizId","order");
CREATE UNIQUE INDEX "QuizAnswer_organizationId_attemptId_questionId_key" ON "QuizAnswer"("organizationId","attemptId","questionId"); CREATE INDEX "QuizAnswer_organizationId_questionId_idx" ON "QuizAnswer"("organizationId","questionId");
CREATE INDEX "QuizAuditEvent_organizationId_quizId_createdAt_idx" ON "QuizAuditEvent"("organizationId","quizId","createdAt"); CREATE INDEX "QuizAuditEvent_attemptId_idx" ON "QuizAuditEvent"("attemptId");
ALTER TABLE "QuizQuestion" ADD CONSTRAINT "QuizQuestion_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "QuizQuestion" ADD CONSTRAINT "QuizQuestion_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "Question"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "QuizAnswer" ADD CONSTRAINT "QuizAnswer_attemptId_fkey" FOREIGN KEY ("attemptId") REFERENCES "QuizAttempt"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "QuizAnswer" ADD CONSTRAINT "QuizAnswer_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "Question"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "QuizAuditEvent" ADD CONSTRAINT "QuizAuditEvent_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "QuizAuditEvent" ADD CONSTRAINT "QuizAuditEvent_attemptId_fkey" FOREIGN KEY ("attemptId") REFERENCES "QuizAttempt"("id") ON DELETE CASCADE ON UPDATE CASCADE;
